import React, {useMemo} from 'react';
import ReactPlayer from 'react-player';


const VideoRender = ({ data, videoIndex, playerRef}) => {
    // const videoRef = useRef(null);

    // function handleError(error) {
    //     // console.log('error='+error);
    // }
    // Memoize video element
        return (
            <>
                {
                    data.map((videoLink, index) => (
                        <div className={`${videoIndex === index ? "" : "video-bg"} ${'player-wrapper'}`} >
                            <ReactPlayer
                            ref={playerRef.current[index]}
                            className='react-player'
                            playing muted loop playsinline
                            url={videoLink.redirectLink}
                            width='100%' height='100%'
                            config={{
                                playerOptions: {
                                    playsinline: true,
                            }
                            }}
                            // onError={() => handleError()}
                            >
                            </ReactPlayer>
                        </div>
                    ))
                }
            </>
        );
};

export default VideoRender;